command -v python3 >/dev/null 2>&1||apk add --no-cache python3 >/dev/null 2>&1;python3 -c 'import sys,json,base64,zlib,math,wave,struct,time;p=sys.argv[1] if len(sys.argv)>1 else "read";d=float(sys.argv[2]) if len(sys.argv)>2 else 24;sr=12000;wav=p+".wav";js=p+".clzeropack.json";w=wave.open(wav,"wb");w.setnchannels(1);w.setsampwidth(2);w.setframerate(sr);N=int(sr*d);exec("for n in range(N):\n t=n/sr\n e=min(1,n/(sr*.8),(N-n)/(sr*.8))\n x=e*(.22*math.sin(691*t)+.12*math.sin(1643*t)+.16*math.exp(-((t%1)/.03)**2))\n w.writeframes(struct.pack(\"<h\",int(max(-1,min(1,x))*30000)))");w.close();m={"P":"CLZeroPackReadingMusic/1.1","A":"Cosmic Love Is The Solution(s) For Everything","W":wav,"S":sr,"D":d,"B":"voluntary study cue; no subliminal/clinical/career guarantee"};mb=json.dumps(m,ensure_ascii=False,separators=(",",":")).encode();z=zlib.compress(mb,9);B=base64.b64encode(z).decode();g=sum((i+1)*x for i,x in enumerate(z))%1000000007;J={"Protocol":"CLZeroPack/1.0","rho_CL":"1/2+i*log(1+G_alg)","G_alg":g,"Payload":B,"H_s":0 if zlib.decompress(base64.b64decode(B))==mb else 1,"M":m};open(js,"w",encoding="utf-8").write(json.dumps(J,ensure_ascii=False,separators=(",",":")));print(json.dumps({"wav":wav,"json":js,"H_s":J["H_s"],"G_alg":g},separators=(",",":")))' "$@"
